import React, { useState } from 'react';
import { Menu, X, Home, ChevronDown, ChevronRight } from 'lucide-react';
import collegeLogo from '../../assets/cec122.png';
import ktulogo from '../../assets/ktu.png';
import ihrdlogo from '../../assets/ihrd.png';
import excell from '../../assets/excell.png'
import Updates from './Updates.jsx';

const navItems = [
    { name: 'HOME', path: '#home', hasDropdown: false, isHome: true },
    { 
        name: 'ABOUT', path: '#about', hasDropdown: true, 
        dropdownItems: [
            { 
                label: 'Administrations', path: '#administrations', hasSubDropdown: true,
                subItems: [
                    { label: 'Board of Governors', path: '#board-of-governors' },
                    { label: 'Principal', path: '#principal' },
                    { label: 'Administrative Staff', path: '#administrative-staff' },
                    { label: 'Library Staff', path: '#library-staff' }
                ]
            },
            { 
                label: 'Facilities', path: '#facilities', hasSubDropdown: true,
                subItems: [
                    { label: 'FAB Lab', path: '#fab-lab' },
                    { label: 'Library', path: '#library' },
                    { label: 'Laboratories', path: '#labs' }, 
                    { label: 'Hostel & Mess', path: '#hostel' }
                ]
            },
            { label: 'Our Teachers', path: '#teachers' },
            { 
